-- Audit events are generated by trusted database triggers, not by a client-callable RPC.
drop function if exists public.record_audit_event(text, text, uuid, jsonb);

create or replace function public.audit_mentee_pathway_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.audit_events (actor_id, action, entity_type, entity_id, metadata)
  values (
    new.mentee_id,
    case when tg_op = 'INSERT' then 'mentee_pathway_created' else 'mentee_pathway_updated' end,
    'mentee_pathway',
    new.id,
    jsonb_build_object('status', new.status, 'pathway_id', new.pathway_id)
  );
  return new;
end;
$$;

revoke all on function public.audit_mentee_pathway_change() from public, anon, authenticated;

drop trigger if exists audit_mentee_pathway_change on public.mentee_pathways;
create trigger audit_mentee_pathway_change
after insert or update of status, pathway_id on public.mentee_pathways
for each row execute function public.audit_mentee_pathway_change();
